int main() {
    string input;
    getline(cin, input);
​
    vector<string> ans = split(input, " ");
    vector<string> res;
    int n = ans.size();
    if (n == 1) {
        cout << ans[0];
        return 0;
    }
    dfs(ans, n, 0, res);
​
    // 输出结果
    for (int i = 0; i < res.size(); i++) {
        cout << res[i];
        if (i != res.size() -1) {
            cout << " ";
        }
    }
​
    return 0;
}
