#include <stdio.h>
#include <stdbool.h>
​
#define MAX_N 1000
​
// DFS 遍历，返回是否有子节点
bool dfs(int ans[], int n, int pos, int res[], int *resCount) {
    if (pos >= n) return false; // 越界，说明该节点不存在
​
    // 左右子节点下标
    bool left = dfs(ans, n, 2 * pos + 1, res, resCount);
    bool right = dfs(ans, n, 2 * pos + 2, res, resCount);
​
    // 如果有子节点，则不是叶子节点，加入结果
    if (left || right) {
        res[(*resCount)++] = ans[pos];
    }
    return true;
}
​
int main() {
    int ans[MAX_N];
    int n = 0;
​
    // 用 scanf 读整数直到 EOF
    while (scanf("%d", &ans[n]) == 1) {
        n++;
    }
​
    int res[MAX_N];
    int resCount = 0;
​
    // 特殊情况：只有一个节点
    if (n == 1) {
        printf("%d\n", ans[0]);
        return 0;
    }
​
    // 从根节点开始 DFS
    dfs(ans, n, 0, res, &resCount);
​
    // 输出结果
    for (int i = 0; i < resCount; i++) {
        printf("%d", res[i]);
        if (i != resCount - 1) printf(" ");
    }
    printf("\n");
​
    return 0;
}
