public class Main {
    // 递归遍历树，获取非叶子节点
    public static boolean dfs(List<String> ans, int n, int pos, List<String> res) {
        if (pos >= n) {
            return false;
        }
        // 左子节点索引 2 * pos + 1
        boolean left = dfs(ans, n, 2 * pos + 1, res);
        // 右子节点索引 2 * (pos + 1)
        boolean right = dfs(ans, n, 2 * (pos + 1), res);
        // 如果不是叶子节点，则添加到结果中
        if (left || right) {
            res.add(ans.get(pos));
        }
        return true;
    }
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] ans = scanner.nextLine().split(" ");
        scanner.close();
​
        List<String> res = new ArrayList<>();
        int n = ans.length;
​
        if (n == 1) {
            System.out.println(ans[0]);
            return;
        }
​
        dfs(Arrays.asList(ans), n, 0, res);

        // 输出结果
        System.out.println(String.join(" ", res));
    }
}
