package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
)
​
// 递归遍历树，获取非叶子节点
func dfs(ans []string, n int, pos int, res *[]string) bool {
    if pos >= n {
        return false
    }
    left := dfs(ans, n, 2*pos+1, res)
    right := dfs(ans, n, 2*(pos+1), res)
    if left || right {
        *res = append(*res, ans[pos])
    }
    return true
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    line, _ := reader.ReadString('\n')
    ans := strings.Fields(strings.TrimSpace(line))
    n := len(ans)
    var res []string
​
    if n == 1 {
        fmt.Println(ans[0])
        return
    }
​
    dfs(ans, n, 0, &res)
    fmt.Println(strings.Join(res, " "))
}
